"Найди значение выражения 96 : c − 4 при c = 8.": "c = 8 болғанда 96 : c − 4 өрнегінің мәнін тап.",
"Вычисли удобным способом: 560 − (160 + 75) = ?": "Ыңғайлы тәсілмен есепте: 560 − (160 + 75) = ?",
"Составную задачу можно решить одним действием.": "Құрама есепті бір әрекетпен шығаруға болады.",
"Две через середины сторон и две по диагоналям.": "Екеуі қабырғалардың орталары арқылы, екеуі диагональдар бойымен.",
"Найди лишнее число в ряду: 2, 4, 6, 9, 10, 12.": "Тізбектегі артық санды тап: 2, 4, 6, 9, 10, 12.",
"Было 90 тг, потратили 35 тг. Сколько осталось?": "90 тг болды, 35 тг жұмсады. Қанша қалды?",
