"Сначала упрости левую часть, потом найди корень.": "Алдымен сол жағын ықшамда, содан кейін түбірін тап.",
"Число увеличили, значит, прибавили: x + 15 = 60.": "Сан артты, демек, қосты: x + 15 = 60.",
