"Найди значение выражения 120 : (m + 2) при m = 4.": "m = 4 болғанда 120 : (m + 2) өрнегінің мәнін тап.",
"Подставляем и получаем верное числовое равенство.": "Қойып, дұрыс сандық теңдік аламыз.",
