"прямые углы: угол между стенами комнаты (это 90°)": "тік бұрыштар: бөлме қабырғаларының арасындағы бұрыш (бұл 90°)",
"Какое число удовлетворяет неравенству 15 < x < 30?": "Қандай сан 15 < x < 30 теңсіздігін қанағаттандырады?",
"буквенное выражение, которое можно упростить до 5b": "5b-ға дейін ықшамдауға болатын әріпті өрнек",
"Например, на сколько 120 больше 85: 120 − 85 = 35.": "Мысалы, 120 саны 85-тен қаншаға үлкен: 120 − 85 = 35.",
"Деление проверяют вычитанием делителя из делимого.": "Бөлуді бөлінгіштен бөлгішті азайтып тексереді.",
