"6/10 больше, чем 4/10, потому что 6 больше 4.": "6/10 4/10-тан үлкен, себебі 6 саны 4-тен үлкен.",
"от перестановки слагаемых сумма увеличивается": "қосылғыштардың орнын ауыстырғанда қосынды артады",
"Сколько литров воды в бассейне объёмом 80 м³?": "Көлемі 80 м³ бассейнде неше литр су бар?",
