"Реши уравнение: x + 345 = 1 200. Чему равен x?": "Теңдеуді шеш: x + 345 = 1 200. x неге тең?",
"Объём коробки 4 см, 5 см и 6 см равен 120 см³.": "Өлшемдері 4 см, 5 см және 6 см қорап көлемі 120 см³-қа тең.",
"Центр транспортира совмещают с концом линейки.": "Транспортирдің центрін сызғыштың ұшымен беттестіреді.",
"Сколько осей можно провести через центр круга?": "Дөңгелектің центрі арқылы неше симметрия осін жүргізуге болады?",
"уравнения: x + 17 = 40 (неизвестное слагаемое)": "теңдеулер: x + 17 = 40 (белгісіз қосылғыш)",
"Число 15 удовлетворяет неравенству 15 < x < 20.": "15 саны 15 < x < 20 теңсіздігін қанағаттандырады.",
"скобка и вычитание: (x + 30) − 12 = 36 (x = 18)": "жақша және азайту: (x + 30) − 12 = 36 (x = 18)",
