"Объём куба равен 125 дм³. Чему равно его ребро?": "Куб көлемі 125 дм³-қа тең. Оның қыры неге тең?",
"Равны две стороны — треугольник равнобедренный.": "Екі қабырғасы тең — үшбұрыш теңбүйірлі.",
"80 + 60 + 40 = 180° — такой треугольник бывает.": "80 + 60 + 40 = 180° — мұндай үшбұрыш болады.",
