"Число должно подходить обоим неравенствам сразу.": "Сан екі теңсіздікке де бірден келуі керек.",
"Значение выражения 48 : c + 5 при c = 6 равно 6.": "c = 6 болғанда 48 : c + 5 өрнегінің мәні 6-ға тең.",
"x = 360 : 30 = 12. Делитель = делимое : частное.": "x = 360 : 30 = 12. Бөлгіш = бөлінгіш : бөлінді.",
"Вспомни формулы S = v · t, t = S : v, v = S : t.": "S = v · t, t = S : v, v = S : t формулаларын еске түсір.",
"проверяем сложением: 93 − 48 = 45 (93 − 48 = 45)": "қосу арқылы тексереміз: 93 − 48 = 45 (93 − 48 = 45)",
"Площадь прямоугольника 9 см × 6 см равна 15 см².": "Өлшемі 9 см × 6 см тіктөртбұрыштың ауданы 15 см²-қа тең.",
"25 = 100 : 4. Поэтому 36 · 25 = 3 600 : 4 = 900.": "25 = 100 : 4. Сондықтан 36 · 25 = 3 600 : 4 = 900.",
"У неравенства 9 < x < 10 нет натуральных решений.": "9 < x < 10 теңсіздігінің натурал шешімі жоқ.",
"Задуманное число уменьшили в 3 раза и получили 12": "Ойланған санды 3 есе кемітіп, 12 алдық",
"Значение слева: 7/12, справа: 5/12. Запись верна.": "Сол жақтың мәні: 7/12, оң жақтікі: 5/12. Жазба дұрыс.",
"Какое свойство записано равенством a · b = b · a?": "a · b = b · a теңдігімен қандай қасиет жазылған?",
