"Число 200 удовлетворяет неравенству 130 < x < 182.": "200 саны 130 < x < 182 теңсіздігін қанағаттандырады.",
"Значение слева: 9/20, справа: 13/20. Запись верна.": "Сол жақтың мәні: 9/20, оң жақтікі: 13/20. Жазба дұрыс.",
"Вычитаемое = уменьшаемое − разность: 90 − 35 = 55.": "Азайғыш = азайтылғыш − айырма: 90 − 35 = 55.",
"Сравни стороны или посмотри на самый большой угол.": "Қабырғаларын салыстыр немесе ең үлкен бұрышына қара.",
"Представь, из каких плоских частей склеена фигура.": "Фигура қандай жазық бөліктерден желімделгенін елестет.",
"На ферме 36 овец и 14 коз. Сколько всего животных?": "Фермада 36 қой мен 14 ешкі бар. Барлығы неше жануар?",
"Подходят числа от 131 до 139. Их 140 − 130 − 1 = 9.": "131-ден 139-ға дейінгі сандар келеді. Олардың саны 140 − 130 − 1 = 9.",
"Запиши выражением: сумму чисел a и 9 умножили на 4.": "Өрнекпен жаз: a және 9 сандарының қосындысын 4-ке көбейттік.",
"объём меньше 100 см³: рёбра 3, 4, 5 см (V = 60 см³)": "көлемі 100 см³-тан кіші: қырлары 3, 4, 5 см (V = 60 см³)",
